package com.tobchestroulette;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

@Getter
@RequiredArgsConstructor
public enum SpinPattern
{
	/**
	 * Sweep back and forth along the row of chests.
	 */
	SWEEP("Sweep"),
	/**
	 * Go round and round, jumping from the last chest back to the first.
	 */
	LOOP("Loop");

	private final String name;

	@Override
	public String toString()
	{
		return name;
	}
}

