package com.tobchestroulette;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Random;
import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * A pre-computed roulette run: which position is highlighted when, and for how long.
 * <p>
 * Positions are indexes into the ordered list of chests the plugin passes in. The plan is built
 * only from the number of positions, the target position and a {@link Random}; it never sees
 * whether any chest is purple, so the shape of the spin (near-misses, false stops) cannot give away
 * loot information.
 */
@Getter
final class SpinPlan
{
	enum Kind
	{
		SPIN,       // normal move
		NEAR_MISS,  // slows almost to a stop, then carries on
		FALSE_STOP, // looks exactly like the real landing, then carries on
		FINAL,      // the real landing on the player's chest
	}

	@Getter
	@RequiredArgsConstructor
	static final class Step
	{
		private final int position;
		private final long startMs;
		private final long holdMs;
		private final Kind kind;
		// Show the highlighted chest as purple for this step. Random, never on a stop.
		private final boolean purpleTease;

		long endMs()
		{
			return startMs + holdMs;
		}

		// False stops are drawn exactly like the real landing.
		boolean looksLanded()
		{
			return kind == Kind.FALSE_STOP || kind == Kind.FINAL;
		}
	}

	private enum Move
	{
		ADVANCE,
		BACK,
	}

	@RequiredArgsConstructor
	private static final class ScriptedMove
	{
		private final Move move;
		private final long holdMs;
		private final Kind kind;
	}

	private final List<Step> steps;
	// When the roulette lands on the target for good (start of the FINAL step).
	private final long landMs;

	private SpinPlan(List<Step> steps)
	{
		this.steps = Collections.unmodifiableList(steps);
		this.landMs = steps.get(steps.size() - 1).getStartMs();
	}

	Step stepAt(long elapsedMs)
	{
		// Plans are at most a few dozen steps; a linear scan is fine.
		for (Step s : steps)
		{
			if (elapsedMs < s.endMs())
			{
				return s;
			}
		}
		return steps.get(steps.size() - 1);
	}

	// Index of the step at this time; the plugin plays one tick sound per new step.
	int stepIndexAt(long elapsedMs)
	{
		for (int i = 0; i < steps.size(); i++)
		{
			if (elapsedMs < steps.get(i).endMs())
			{
				return i;
			}
		}
		return steps.size() - 1;
	}

	// ---------------------------------------------------------------------------------------------
	// Generation
	// ---------------------------------------------------------------------------------------------

	// How long the roulette stays on each chest at the start and end of the slowdown, at Normal speed.
	private static final long FAST_HOLD_MS = 80;
	private static final long SLOW_HOLD_MS = 500;
	// Shortest main run allowed even if fake-outs use up the rest of the time.
	private static final long MIN_MAIN_MS = 1200;
	// Shortest a fake-out pause is squeezed to on very short spins.
	private static final long MIN_TAIL_HOLD_MS = 120;

	/**
	 * @param positions number of roulette positions (at least 2; a solo raid adds an empty position so the
	 *                  roulette can blink on and off over the one chest)
	 * @param target    the position the plan must finish on
	 * @param landAtMs  when the highlight should settle on the target, i.e. the configured spin duration
	 */
	static SpinPlan generate(int positions, int target, long landAtMs, SpinSpeed speed, FakeOuts fakeOuts,
		SpinPattern pattern, double teaseChance, Random rng)
	{
		if (positions < 2)
		{
			throw new IllegalArgumentException("need at least 2 positions, got " + positions);
		}
		if (target < 0 || target >= positions)
		{
			throw new IllegalArgumentException("target " + target + " out of range");
		}

		double pace = speed.getHoldScale();
		List<ScriptedMove> tail = buildTail(fakeOuts, pace, rng);
		long tailBeforeLanding = tailBeforeLanding(tail);

		// Fake-outs must not push the landing past the configured duration: compress the whole tail
		// (FINAL included, so false stops and the real stop stay the same length) to leave room
		// for the main run.
		long tailRoom = landAtMs - MIN_MAIN_MS;
		if (tailBeforeLanding > tailRoom && tailBeforeLanding > 0)
		{
			double factor = Math.max(0, (double) tailRoom / tailBeforeLanding);
			List<ScriptedMove> scaled = new ArrayList<>(tail.size());
			for (ScriptedMove m : tail)
			{
				scaled.add(new ScriptedMove(m.move, Math.max(MIN_TAIL_HOLD_MS, Math.round(m.holdMs * factor)), m.kind));
			}
			tail = scaled;
			tailBeforeLanding = tailBeforeLanding(tail);
		}

		// After compression this is within rounding of MIN_MAIN_MS; only the per-hold floor on
		// very short spins can push it lower, and even then the main run keeps half its minimum.
		long mainBudget = Math.max(MIN_MAIN_MS / 2, landAtMs - tailBeforeLanding);
		List<Long> mainHolds = easeOutHolds(mainBudget, positions, pace, rng);

		List<ScriptedMove> script = new ArrayList<>();
		// The first main hold belongs to the starting position, every other one to an ADVANCE.
		for (int i = 1; i < mainHolds.size(); i++)
		{
			script.add(new ScriptedMove(Move.ADVANCE, mainHolds.get(i), Kind.SPIN));
		}
		script.addAll(tail);

		int[] start = pickStart(positions, target, script, pattern, rng);

		List<Step> steps = new ArrayList<>(script.size() + 1);
		int pos = start[0];
		int dir = start[1];
		long t = 0;
		steps.add(new Step(pos, t, mainHolds.get(0), Kind.SPIN, tease(Kind.SPIN, teaseChance, rng)));
		t += mainHolds.get(0);
		for (ScriptedMove m : script)
		{
			int[] next = apply(pos, dir, m.move, positions, pattern);
			pos = next[0];
			dir = next[1];
			steps.add(new Step(pos, t, m.holdMs, m.kind, tease(m.kind, teaseChance, rng)));
			t += m.holdMs;
		}
		return new SpinPlan(steps);
	}

	/**
	 * Hold times that start fast and slow down (ease-out in speed = ease-in in hold time),
	 * summing to roughly {@code budget}.
	 */
	private static List<Long> easeOutHolds(long budget, int positions, double pace, Random rng)
	{
		long fast = jitter(Math.round(FAST_HOLD_MS * pace), 0.15, rng);
		long slow = jitter(Math.round(SLOW_HOLD_MS * pace), 0.20, rng);
		double curve = 2.0 + rng.nextDouble() * 0.8;
		int minSteps = Math.max(6, positions * 2);

		for (int n = minSteps; ; n++)
		{
			List<Long> holds = new ArrayList<>(n);
			long sum = 0;
			for (int k = 0; k < n; k++)
			{
				double u = n == 1 ? 1 : (double) k / (n - 1);
				long h = Math.round(fast + (slow - fast) * Math.pow(u, curve));
				// small per-tick wobble so it never feels metronomic, but never faster than the previous tick
				h = jitter(h, 0.08, rng);
				if (k > 0)
				{
					h = Math.max(h, holds.get(k - 1));
				}
				holds.add(h);
				sum += h;
			}
			if (sum >= budget || n > 400)
			{
				// Scale onto the budget exactly so the landing time matches the configured duration.
				// Rounding the running total keeps each hold within 1ms, so it never speeds back up.
				double scale = (double) budget / sum;
				List<Long> scaled = new ArrayList<>(n);
				double ideal = 0;
				long placed = 0;
				for (int k = 0; k < n; k++)
				{
					ideal += holds.get(k) * scale;
					long end = k == n - 1 ? budget : Math.round(ideal);
					scaled.add(end - placed);
					placed = end;
				}
				return scaled;
			}
		}
	}

	/**
	 * The fake-out section after the main slowdown, ending with the FINAL landing move.
	 */
	private static List<ScriptedMove> buildTail(FakeOuts fakeOuts, double pace, Random rng)
	{
		int count;
		switch (fakeOuts)
		{
			case LIGHT:
				count = rng.nextDouble() < 0.65 ? 1 : 0;
				break;
			case CHAOTIC:
				count = 2 + rng.nextInt(2);
				break;
			case OFF:
			default:
				count = 0;
				break;
		}

		List<ScriptedMove> tail = new ArrayList<>();
		boolean lastWasTickBack = false;
		for (int i = 0; i < count; i++)
		{
			lastWasTickBack = false;
			switch (rng.nextInt(3))
			{
				case 0:
					// near-miss: crawl onto a chest, hold a beat, tick over
					tail.add(new ScriptedMove(Move.ADVANCE, range(650, 1100, pace, rng), Kind.NEAR_MISS));
					break;
				case 1:
				{
					// false stop: look exactly like the landing, then carry on one or two chests
					tail.add(new ScriptedMove(Move.ADVANCE, landedHold(pace, rng), Kind.FALSE_STOP));
					int more = fakeOuts == FakeOuts.CHAOTIC ? 1 + rng.nextInt(2) : 1;
					for (int j = 0; j < more - 1; j++)
					{
						tail.add(new ScriptedMove(Move.ADVANCE, range(380, 620, pace, rng), Kind.SPIN));
					}
					break;
				}
				default:
					// tick-back: overshoot by one with a near-stop, then tick back
					tail.add(new ScriptedMove(Move.ADVANCE, range(700, 1150, pace, rng), Kind.NEAR_MISS));
					tail.add(new ScriptedMove(Move.BACK, range(450, 700, pace, rng), Kind.SPIN));
					lastWasTickBack = true;
					break;
			}
		}

		if (lastWasTickBack)
		{
			// the tick back itself is the landing
			ScriptedMove back = tail.remove(tail.size() - 1);
			tail.add(new ScriptedMove(back.move, landedHold(pace, rng), Kind.FINAL));
		}
		else
		{
			tail.add(new ScriptedMove(Move.ADVANCE, landedHold(pace, rng), Kind.FINAL));
		}
		return tail;
	}

	/**
	 * Purple teases are pure chance and never happen on a stop, so a purple flash can't tell you
	 * anything about the real loot or whether a stop is fake.
	 */
	private static boolean tease(Kind kind, double chance, Random rng)
	{
		return (kind == Kind.SPIN || kind == Kind.NEAR_MISS) && rng.nextDouble() < chance;
	}

	private static long tailBeforeLanding(List<ScriptedMove> tail)
	{
		long sum = 0;
		for (int i = 0; i < tail.size() - 1; i++)
		{
			sum += tail.get(i).holdMs;
		}
		return sum;
	}

	/**
	 * Shared by FALSE_STOP and FINAL so the two are indistinguishable.
	 */
	private static long landedHold(double pace, Random rng)
	{
		return range(1100, 1700, pace, rng);
	}

	/**
	 * Find a start (position, direction) from which the script ends on {@code target}; picks
	 * randomly among all that work so the starting chest is not predictable either.
	 */
	private static int[] pickStart(int positions, int target, List<ScriptedMove> script, SpinPattern pattern, Random rng)
	{
		List<int[]> candidates = new ArrayList<>();
		for (int p = 0; p < positions; p++)
		{
			for (int d : new int[]{1, -1})
			{
				int pos = p;
				int dir = d;
				for (ScriptedMove m : script)
				{
					int[] next = apply(pos, dir, m.move, positions, pattern);
					pos = next[0];
					dir = next[1];
				}
				if (pos == target)
				{
					candidates.add(new int[]{p, d});
				}
			}
		}
		if (candidates.isEmpty())
		{
			// Every move is invertible in both patterns so this cannot happen; fail loudly if it ever does.
			throw new IllegalStateException("no start state reaches target " + target);
		}
		return candidates.get(rng.nextInt(candidates.size()));
	}

	/**
	 * @return {newPosition, newDirection}
	 */
	private static int[] apply(int pos, int dir, Move move, int positions, SpinPattern pattern)
	{
		if (move == Move.BACK)
		{
			dir = -dir;
		}
		if (pattern == SpinPattern.LOOP)
		{
			return new int[]{Math.floorMod(pos + dir, positions), dir};
		}
		// SWEEP: bounce off the ends
		int next = pos + dir;
		if (next < 0 || next >= positions)
		{
			dir = -dir;
			next = pos + dir;
		}
		return new int[]{next, dir};
	}

	private static long range(long lo, long hi, double pace, Random rng)
	{
		return Math.round((lo + rng.nextDouble() * (hi - lo)) * pace);
	}

	private static long jitter(long v, double frac, Random rng)
	{
		return Math.max(1, Math.round(v * (1 + (rng.nextDouble() * 2 - 1) * frac)));
	}
}

