package com.tobchestroulette;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

@Getter
@RequiredArgsConstructor
public enum SpinSpeed
{
	SLOW("Slow", 1.6),
	NORMAL("Normal", 1.0),
	FAST("Fast", 0.65);

	private final String name;
	// Multiplier on how long the roulette stays on each chest.
	private final double holdScale;

	@Override
	public String toString()
	{
		return name;
	}
}

