package com.tobchestroulette;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup("tobchestroulette")
public interface TobChestRouletteConfig extends Config
{
	@ConfigSection(
		name = "Spin",
		description = "How the roulette looks and moves",
		position = 0
	)
	String spinSection = "spin";

	@ConfigSection(
		name = "Reveal",
		description = "What happens when you open your chest",
		position = 1
	)
	String revealSection = "reveal";

	@Range(min = 3, max = 30)
	@Units(Units.SECONDS)
	@ConfigItem(
		keyName = "spinDuration",
		name = "Spin duration",
		description = "How long the roulette spins before landing on your chest.",
		position = 0,
		section = spinSection
	)
	default int spinDuration()
	{
		return 8;
	}

	@ConfigItem(
		keyName = "spinSpeed",
		name = "Spin speed",
		description = "How quickly the roulette moves from chest to chest, and how long its pauses and fake stops last.",
		position = 1,
		section = spinSection
	)
	default SpinSpeed spinSpeed()
	{
		return SpinSpeed.NORMAL;
	}

	@ConfigItem(
		keyName = "indicator",
		name = "Roulette indicator",
		description = "What moves between the chests: the game's own chest arrow, an outline, or both.",
		position = 2,
		section = spinSection
	)
	default RouletteIndicator indicator()
	{
		return RouletteIndicator.ARROW;
	}

	@ConfigItem(
		keyName = "fakeOuts",
		name = "Fake-outs",
		description = "Near-misses and false stops before the real landing. They are random every raid.",
		position = 3,
		section = spinSection
	)
	default FakeOuts fakeOuts()
	{
		return FakeOuts.LIGHT;
	}

	@ConfigItem(
		keyName = "purpleTeases",
		name = "Purple teases",
		description = "Chests sometimes flash purple as the roulette passes them. Purely random: it never means a real purple,<br>"
			+ "and it never happens when the roulette stops.",
		position = 4,
		section = spinSection
	)
