package com.tobchestroulette;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

class TobChestRouletteOverlay extends Overlay
{
	// Pulse speed while the outline has stopped on a chest (a false stop or the real one).
	private static final double LANDED_PULSE_MS = 420.0;
	private static final double PURPLE_PULSE_MS = 300.0;
	private static final long PURPLE_OUTLINE_MS = 3500;
	private static final long PURPLE_FLASH_MS = 700;
	private static final float PURPLE_FLASH_MAX_ALPHA = 0.45f;

	private final Client client;
	private final TobChestRoulettePlugin plugin;
	private final TobChestRouletteConfig config;
	private final ModelOutlineRenderer outlineRenderer;

	@Inject
	TobChestRouletteOverlay(Client client, TobChestRoulettePlugin plugin, TobChestRouletteConfig config, ModelOutlineRenderer outlineRenderer)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.outlineRenderer = outlineRenderer;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPriority(PRIORITY_HIGH);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		TobChestRoulettePlugin.Phase phase = plugin.getPhase();
		long now = TobChestRoulettePlugin.now();

		boolean outline = config.indicator() != RouletteIndicator.ARROW;
		if (phase == TobChestRoulettePlugin.Phase.SPINNING && outline)
		{
			renderSpin(now);
		}
		else if (phase == TobChestRoulettePlugin.Phase.LANDED && outline)
		{
			// Stays on your chest, pulsing like any stop, until you open it.
			GameObject mine = plugin.myChest();
			if (mine != null)
			{
				drawLanded(mine, now - plugin.getLandedAtMs());
			}
		}
		else if (phase == TobChestRoulettePlugin.Phase.REVEALED && plugin.getRevealAtMs() >= 0)
		{
			renderReveal(graphics, now - plugin.getRevealAtMs());
		}
		return null;
	}

	private void renderSpin(long now)
	{
		SpinPlan plan = plugin.getPlan();
		if (plan == null)
		{
			return;
		}
		long elapsed = now - plugin.getSpinStartMs();
		SpinPlan.Step step = plan.stepAt(elapsed);
		GameObject chest = plugin.objectAtPosition(step.getPosition());
		if (chest == null)
		{
			// Solo raid: the "off" half of the blink.
			return;
		}

		if (step.looksLanded())
		{
			drawLanded(chest, elapsed - step.getStartMs());
		}
		else
		{
			outlineRenderer.drawOutline(chest, config.outlineWidth(), config.highlightColor(), config.outlineFeather());
		}
	}

	// Same pulse for false stops and the real stop, so they can't be told apart.
	private void drawLanded(GameObject chest, long sinceStop)
	{
		double pulse = 0.5 + 0.5 * Math.cos(sinceStop / LANDED_PULSE_MS * 2 * Math.PI);
		int width = config.outlineWidth() + (int) Math.round(pulse * 2);
		Color color = scaleAlpha(config.highlightColor(), 0.65 + 0.35 * pulse);
		outlineRenderer.drawOutline(chest, width, color, config.outlineFeather());
	}

	private void renderReveal(Graphics2D graphics, long sinceReveal)
	{
		if (!plugin.isRevealedPurple() || config.purpleRevealEffect() == RevealEffect.NONE)
		{
			return;
		}
		Color purple = config.purpleColor();
		if (sinceReveal < PURPLE_FLASH_MS)
		{
			float alpha = PURPLE_FLASH_MAX_ALPHA * (1f - (float) sinceReveal / PURPLE_FLASH_MS);
			graphics.setColor(new Color(purple.getRed(), purple.getGreen(), purple.getBlue(), Math.round(alpha * 255)));
			graphics.fillRect(client.getViewportXOffset(), client.getViewportYOffset(),
				client.getViewportWidth(), client.getViewportHeight());
		}
		GameObject mine = plugin.myChest();
		if (mine != null && sinceReveal < PURPLE_OUTLINE_MS)
		{
			double fade = 1.0 - (double) sinceReveal / PURPLE_OUTLINE_MS;
			double pulse = 0.5 + 0.5 * Math.cos(sinceReveal / PURPLE_PULSE_MS * 2 * Math.PI);
			int width = config.outlineWidth() + 2 + (int) Math.round(pulse * 3);
			outlineRenderer.drawOutline(mine, width, scaleAlpha(purple, fade), Math.min(4, config.outlineFeather() + 1));
		}
	}

	private static Color scaleAlpha(Color c, double factor)
	{
		int a = (int) Math.round(c.getAlpha() * Math.max(0, Math.min(1, factor)));
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), a);
	}
}

