/**
 * Cosmetic only: hides which Theatre of Blood loot chest is yours, and whether any chest is purple,
 * until a short roulette lands on your chest.
 * <p>
 * Each loot chest ({@code TOB_TREASUREROOM_CHEST_LOC0..4}) picks its look from a varbit
 * ({@code TOB_TREASUREROOM_CHEST_0..4}): 0 = not mine, 1 = not mine + purple, 2 = mine (with the
 * floating arrow), 3 = mine + purple. The plugin keeps those varbits at 0 in the local client, so the
 * game draws every chest plain. During the spin the highlighted chest is set to 2, which makes the game
 * draw its own arrow over it, and now and then to 1 or 3 for a random purple tease. The roulette then
 * stays on your chest until you open it, and only then is its real look shown. Other chests stay plain
 * until you leave. Nothing is sent to the server.
 */
@Slf4j
@PluginDescriptor(
	name = "ToB Chest Roulette",
	description = "Cosmetic: hides which ToB loot chest is yours and whether it's purple until a roulette lands on it",
	tags = {"tob", "theatre", "blood", "raid", "purple", "chest", "loot", "roulette", "spoiler"}
)
public class TobChestRoulettePlugin extends Plugin
{
	private static final int SLOTS = 5;

	private static final int[] CHEST_LOCS = {
		ObjectID.TOB_TREASUREROOM_CHEST_LOC0,
		ObjectID.TOB_TREASUREROOM_CHEST_LOC1,
		ObjectID.TOB_TREASUREROOM_CHEST_LOC2,
		ObjectID.TOB_TREASUREROOM_CHEST_LOC3,
		ObjectID.TOB_TREASUREROOM_CHEST_LOC4,
	};

	// Same order as CHEST_LOCS: each chest loc reads the varbit at the same index.
	private static final int[] CHEST_VARBITS = {
		VarbitID.TOB_TREASUREROOM_CHEST_0,
		VarbitID.TOB_TREASUREROOM_CHEST_1,
		VarbitID.TOB_TREASUREROOM_CHEST_2,
		VarbitID.TOB_TREASUREROOM_CHEST_3,
		VarbitID.TOB_TREASUREROOM_CHEST_4,
	};

	// The varp that holds all five chest varbits.
	private static final int CHEST_VARP = VarPlayerID.TOB_TEMP_TRANSMIT_2;

	private static final int NOT_MINE = 0;
	private static final int NOT_MINE_PURPLE = 1;
	private static final int MINE = 2;
	private static final int MINE_PURPLE = 3;

	// Share of roulette steps where the highlighted chest flashes purple, when teases are on.
	private static final double TEASE_CHANCE = 0.2;

	// Theatre of Blood loot room.
	private static final int LOOT_ROOM_REGION = 12867;

	// A game hint arrow this many tiles from a chest is treated as pointing at it.
	private static final int HINT_ARROW_RANGE = 2;

	private static final String TOB_LIGHT_COLORS = "ToB Light Colors";
	private static final String TOB_QOL = "ToB QoL";
	private static final String ODABLOCK = "Odablock Plugin";

	enum Phase
	{
		IDLE,      // nothing hidden
		HIDDEN,    // loot assigned, chests shown plain, waiting for the player to enter the room
		SPINNING,
		LANDED,    // the roulette is on your chest, still plain, until you open it
		REVEALED,  // you opened your chest; its real look is shown
	}

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private TobChestRouletteConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private TobChestRouletteOverlay overlay;

	@Inject
	private PluginManager pluginManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	private final Random random = new Random();

	private final GameObject[] chests = new GameObject[SLOTS];
	// Where your chest stands, and the opened chest the game puts there once you open it.
	@Nullable
	private WorldPoint myChestLocation;
	@Nullable
	private GameObject openedChest;
	// The server's value for each chest varbit, -1 if unknown.
	private final int[] realValue = new int[SLOTS];
	// The value this plugin last put in each chest varbit, -1 if none.
	private final int[] written = new int[SLOTS];
	private final boolean[] revealed = new boolean[SLOTS];

	@Getter(AccessLevel.PACKAGE)
	private Phase phase = Phase.IDLE;
	private int mySlot = -1;
	// The chest the roulette is on, and the look it is given (arrow and/or purple tease).
	private int shownSlot = -1;
	private int shownValue = NOT_MINE;

	@Getter(AccessLevel.PACKAGE)
	private SpinPlan plan;
	// Chest slot for each roulette position; -1 is the empty position used to blink in solo raids.
	private int[] positionSlots;
	@Getter(AccessLevel.PACKAGE)
	private long spinStartMs;
	private int lastStep = -1;

	@Getter(AccessLevel.PACKAGE)
	private long landedAtMs = -1;
	@Getter(AccessLevel.PACKAGE)
	private long revealAtMs = -1;
	@Getter(AccessLevel.PACKAGE)
	private boolean revealedPurple;

	@Nullable
	private WorldPoint hiddenHintArrow;
	private boolean inLootRoom;
	private boolean seenLootRoom;
	private boolean writing;
	private boolean warned;

	@Override
	protected void startUp()
	{
		Arrays.fill(realValue, -1);
		Arrays.fill(written, -1);
		overlayManager.add(overlay);
		clientThread.invoke(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				findChestsInScene();
				sync();
			}
		});
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		clientThread.invoke(() ->
		{
			// Turned off mid-spin: give back the hint arrow we hid.
			if (hiddenHintArrow != null && client.getGameState() == GameState.LOGGED_IN)
			{
				client.setHintArrow(hiddenHintArrow);
			}
			reset();
		});
	}

	@Provides
	TobChestRouletteConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(TobChestRouletteConfig.class);
	}

	// High priority: hide the new value before other plugins see it.
	@Subscribe(priority = 1000)
	public void onVarbitChanged(VarbitChanged event)
	{
		if (!writing && event.getVarpId() == CHEST_VARP)
		{
			sync();
		}
	}

	// High priority: hide the chest before other plugins (e.g. 117 HD's lights) look at it.
	@Subscribe(priority = 1000)
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		GameObject object = event.getGameObject();
		int slot = slotOf(object.getId());
		if (slot >= 0)
		{
			chests[slot] = object;
			sync();
		}
		else if ((object.getId() == ObjectID.TOB_TREASUREROOM_CHEST_OPEN || object.getId() == ObjectID.TOB_TREASUREROOM_CHEST_OPEN_RARE)
			&& object.getWorldLocation().equals(myChestLocation))
		{
			openedChest = object;
		}
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		int slot = slotOf(event.getGameObject().getId());
		if (event.getGameObject() == openedChest)
		{
			openedChest = null;
		}
		if (slot >= 0 && chests[slot] == event.getGameObject())
		{
			chests[slot] = null;
			if (slot == mySlot && inLootRoom && client.getGameState() == GameState.LOGGED_IN)
			{
				// Your chest was replaced by the opened chest.
				revealMine();
			}
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING || state == GameState.CONNECTION_LOST)
		{
			reset();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		inLootRoom = isInLootRoom();
		if (phase == Phase.IDLE)
		{
			return;
		}

		if (inLootRoom)
		{
			seenLootRoom = true;
		}
		else if (seenLootRoom && !anyChestPresent())
		{
			// Left the raid.
			reset();
			return;
		}

		if (phase == Phase.SPINNING && !inLootRoom)
		{
			// Walked out mid-spin: spin again on the way back in.
			phase = Phase.HIDDEN;
			plan = null;
		}
		else if (phase == Phase.HIDDEN && inLootRoom && chests[mySlot] != null)
		{
			startSpin();
		}

		if (!warned)
		{
			warned = true;
			warnAboutConflicts();
		}
	}

	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		if (phase == Phase.IDLE && !anyChestPresent())
		{
			return;
		}

		shownSlot = -1;
		boolean arrow = config.indicator() != RouletteIndicator.OUTLINE;
		if (phase == Phase.SPINNING)
		{
			advanceSpin(arrow);
		}
		if (phase == Phase.LANDED && arrow)
		{
			// The game's own arrow stays over your still-plain chest.
			shownSlot = mySlot;
			shownValue = MINE;
		}

		sync();

		if (phase == Phase.HIDDEN || phase == Phase.SPINNING)
		{
			hideHintArrow();
		}
	}

	/**
	 * Moves the roulette on for this frame: ticks, picks the chest to show, and lands when time is up.
	 */
	private void advanceSpin(boolean arrow)
	{
		long elapsed = now() - spinStartMs;
		int step = plan.stepIndexAt(elapsed);
		if (step != lastStep)
		{
			lastStep = step;
			if (config.tickSound())
			{
				client.playSoundEffect(SoundEffectID.GE_INCREMENT_PLOP);
			}
		}

		if (elapsed >= plan.getLandMs())
		{
			land();
			return;
		}

		SpinPlan.Step current = plan.stepAt(elapsed);
		boolean purple = current.isPurpleTease();
		if (arrow || purple)
		{
			shownSlot = slotAtPosition(current.getPosition());
			// With the arrow: "mine" (+ purple for a tease). Outline only: plain purple for a tease.
			shownValue = arrow ? (purple ? MINE_PURPLE : MINE) : NOT_MINE_PURPLE;
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		// The ToB reward window opens when you open your chest.
		if (event.getGroupId() == InterfaceID.TOB_CHESTS && inLootRoom)
		{
			revealMine();
		}
	}

	/**
	 * Keeps the chest varbits in the local client matching what should be shown, and learns the real
	 * values from the server along the way.
	 */
	private void sync()
	{
		if (phase == Phase.IDLE)
		{
			// Nothing is hidden, so the client holds the real values. Start hiding if we have a chest.
			for (int i = 0; i < SLOTS; i++)
			{
				realValue[i] = client.getVarbitValue(CHEST_VARBITS[i]);
				if (isMine(realValue[i]))
				{
					mySlot = i;
				}
			}
			if (mySlot < 0)
			{
				return;
			}
			log.debug("Loot assigned, hiding chests. Real values: {}", Arrays.toString(realValue));
			phase = Phase.HIDDEN;
		}

		for (int i = 0; i < SLOTS; i++)
		{
			if (revealed[i])
			{
				continue;
			}
			int current = client.getVarbitValue(CHEST_VARBITS[i]);
			if (current != written[i])
			{
				// We didn't put this value there, so the server did.
				realValue[i] = current;
				if (isMine(current))
				{
					mySlot = i;
				}
			}
			int wanted = i == shownSlot ? shownValue : NOT_MINE;
			if (current != wanted)
			{
				setVarbit(i, wanted);
			}
			written[i] = wanted;
		}

		if (phase == Phase.HIDDEN && !isMine(realValue[mySlot]))
		{
			// The server cleared the loot (raid over), so there is nothing left to hide.
			reset();
		}
	}

	private static boolean isMine(int value)
	{
		return value == MINE || value == MINE_PURPLE;
	}

	private void startSpin()
	{
		myChestLocation = chests[mySlot].getWorldLocation();
		List<Integer> slots = new ArrayList<>();
		for (int i = 0; i < SLOTS; i++)
		{
			if (chests[i] != null)
			{
				slots.add(i);
			}
		}
		sortAlongRow(slots);

		int target;
		if (slots.size() == 1)
		{
			// Solo: blink on and off over the one chest.
			positionSlots = new int[]{slots.get(0), -1};
			target = 0;
		}
		else
		{
			positionSlots = slots.stream().mapToInt(Integer::intValue).toArray();
			target = slots.indexOf(mySlot);
		}

		plan = SpinPlan.generate(positionSlots.length, target, config.spinDuration() * 1000L,
			config.spinSpeed(), config.fakeOuts(), config.spinPattern(),
			config.purpleTeases() ? TEASE_CHANCE : 0, random);
		spinStartMs = now();
		lastStep = -1;
		phase = Phase.SPINNING;
		log.debug("Spin started over slots {}, lands at {} ms", Arrays.toString(positionSlots), plan.getLandMs());
	}

	private void land()
	{
		phase = Phase.LANDED;
		landedAtMs = now();
		plan = null;
		if (config.restoreHintArrow() && hiddenHintArrow != null)
		{
			client.setHintArrow(hiddenHintArrow);
		}
		hiddenHintArrow = null;
		log.debug("Roulette landed on slot {}", mySlot);
	}

	/**
	 * You opened your chest: show its real look. The other chests stay plain until you leave.
	 */
	private void revealMine()
	{
		if (phase != Phase.HIDDEN && phase != Phase.SPINNING && phase != Phase.LANDED)
		{
			return;
		}
		phase = Phase.REVEALED;
		plan = null;
		shownSlot = -1;
		revealAtMs = now();
		revealedPurple = realValue[mySlot] == MINE_PURPLE;
		reveal(mySlot);
		hiddenHintArrow = null;

		if (revealedPurple && config.purpleRevealEffect() == RevealEffect.FLASH_AND_SOUND)
		{
			client.playSoundEffect(SoundEffectID.GE_ADD_OFFER_DINGALING);
		}
	}

	private void reveal(int slot)
	{
		if (revealed[slot])
		{
			return;
		}
		revealed[slot] = true;
		written[slot] = -1;
		if (realValue[slot] >= 0 && client.getVarbitValue(CHEST_VARBITS[slot]) != realValue[slot])
		{
			setVarbit(slot, realValue[slot]);
		}
	}

	/**
	 * Puts every real value back and forgets the round.
	 */
	private void reset()
	{
		if (phase != Phase.IDLE)
		{
			for (int i = 0; i < SLOTS; i++)
			{
				reveal(i);
			}
		}
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			Arrays.fill(chests, null);
		}
		phase = Phase.IDLE;
		plan = null;
		positionSlots = null;
		mySlot = -1;
		shownSlot = -1;
		landedAtMs = -1;
		revealAtMs = -1;
		revealedPurple = false;
		hiddenHintArrow = null;
		myChestLocation = null;
		openedChest = null;
		seenLootRoom = false;
		warned = false;
		Arrays.fill(realValue, -1);
		Arrays.fill(written, -1);
		Arrays.fill(revealed, false);
	}

	private void setVarbit(int slot, int value)
	{
		// Local client only; never sent to the server.
		writing = true;
		try
		{
			client.setVarbit(CHEST_VARBITS[slot], value);
			// Without this the game keeps drawing the chest's old look. RuneLite's var inspector does the same.
			client.queueChangedVarp(CHEST_VARP);
		}
		finally
		{
			writing = false;
		}
	}

	/**
	 * The game can point a hint arrow at your chest; hide it until the reveal.
	 */
	private void hideHintArrow()
	{
		if (client.getHintArrowType() != HintArrowType.COORDINATE)
		{
			return;
		}
		WorldPoint arrow = client.getHintArrowPoint();
		for (GameObject chest : chests)
		{
			if (arrow != null && chest != null && chest.getWorldLocation().distanceTo(arrow) <= HINT_ARROW_RANGE)
			{
				hiddenHintArrow = arrow;
				client.clearHintArrow();
				return;
			}
		}
	}

	private void warnAboutConflicts()
	{
		if (!config.warnConflicts())
		{
			return;
		}
		if (isPluginEnabled(TOB_LIGHT_COLORS))
		{
			chat("ToB Light Colors is on. This plugin hides the chests from it too, so its beams won't show purples.");
		}
		if (isPluginEnabled(TOB_QOL) && isOn("tobqol", "dryLootTracking"))
		{
			chat("ToB QoL's Dry Loot Tracking is on. It reads the chests before you open yours, so its dry streak "
				+ "count will be wrong. Turn one of the two off.");
		}
		if (isPluginEnabled(ODABLOCK) && (isOn("odablockplugin", "tobWhiteChest") || isOn("odablockplugin", "tobPurpleChest")))
		{
			chat("Odablock's TOB chest sounds are on. They play before the roulette and only see plain chests, so "
				+ "you'll hear the white chest sound even on a purple. Turn off TOB White Chest and TOB Purple Chest "
				+ "in the Odablock plugin.");
		}
	}

	// A boolean setting of another plugin; those default to on here, so only an explicit "false" is off.
	private boolean isOn(String group, String key)
	{
		return !"false".equals(configManager.getConfiguration(group, key));
	}

	private void chat(String message)
	{
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(new ChatMessageBuilder()
				.append(ChatColorType.HIGHLIGHT)
				.append("ToB Chest Roulette: ")
				.append(ChatColorType.NORMAL)
				.append(message)
				.build())
			.build());
	}

	private boolean isPluginEnabled(String name)
	{
		for (Plugin plugin : pluginManager.getPlugins())
		{
			if (name.equals(plugin.getName()))
			{
				return pluginManager.isPluginEnabled(plugin);
			}
		}
		return false;
	}

	@Nullable
	GameObject objectAtPosition(int position)
	{
		int slot = slotAtPosition(position);
		return slot < 0 ? null : chests[slot];
	}

	@Nullable
	GameObject myChest()
	{
		if (mySlot < 0)
		{
			return null;
		}
		return chests[mySlot] != null ? chests[mySlot] : openedChest;
	}

	static long now()
	{
		return System.nanoTime() / 1_000_000L;
	}

	private int slotAtPosition(int position)
	{
		return positionSlots == null ? -1 : positionSlots[position];
	}

	private static int slotOf(int objectId)
	{
		for (int i = 0; i < SLOTS; i++)
		{
			if (CHEST_LOCS[i] == objectId)
			{
				return i;
			}
		}
		return -1;
	}

	private boolean anyChestPresent()
	{
		for (GameObject chest : chests)
		{
			if (chest != null)
			{
				return true;
			}
		}
		return false;
	}

	private boolean isInLootRoom()
	{
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return false;
		}
		WorldPoint location = WorldPoint.fromLocalInstance(client, player.getLocalLocation());
		return location != null && location.getRegionID() == LOOT_ROOM_REGION;
	}

	/**
	 * Orders the chests along the line they stand in, so the highlight steps to the next chest over
	 * instead of jumping around.
	 */
	private void sortAlongRow(List<Integer> slots)
	{
		if (slots.size() < 3)
		{
			return;
		}
		int minX = Integer.MAX_VALUE;
		int maxX = Integer.MIN_VALUE;
		int minY = Integer.MAX_VALUE;
		int maxY = Integer.MIN_VALUE;
		for (int slot : slots)
		{
			LocalPoint p = chests[slot].getLocalLocation();
			minX = Math.min(minX, p.getX());
			maxX = Math.max(maxX, p.getX());
			minY = Math.min(minY, p.getY());
			maxY = Math.max(maxY, p.getY());
		}
		// Sort along whichever direction the chests are spread out in more.
		boolean alongX = maxX - minX >= maxY - minY;
		slots.sort(Comparator.comparingInt(slot ->
		{
			LocalPoint p = chests[slot].getLocalLocation();
			return alongX ? p.getX() : p.getY();
		}));
	}

	/**
	 * For when the plugin is turned on while already in the loot room.
	 */
	private void findChestsInScene()
	{
		for (Tile[][] plane : client.getTopLevelWorldView().getScene().getTiles())
		{
			for (Tile[] row : plane)
			{
				for (Tile tile : row)
				{
					if (tile == null)
					{
						continue;
					}
					for (GameObject object : tile.getGameObjects())
					{
						if (object != null && slotOf(object.getId()) >= 0)
						{
							chests[slotOf(object.getId())] = object;
						}
					}
				}
			}
		}
	}
}

package com.tobchestroulette;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.util.List;
import java.util.Random;
import org.junit.Test;

public class SpinPlanTest
{
	private static final long DURATION_MS = 5000;

	@Test
	public void alwaysLandsOnTarget()
	{
		Random seeds = new Random(1234);
		for (FakeOuts fakeOuts : FakeOuts.values())
		{
			for (SpinPattern pattern : SpinPattern.values())
			{
				for (int positions = 2; positions <= 5; positions++)
				{
					for (int target = 0; target < positions; target++)
					{
						for (int run = 0; run < 200; run++)
						{
							SpinPlan plan = SpinPlan.generate(positions, target, DURATION_MS, SpinSpeed.NORMAL, fakeOuts, pattern, 0.2, new Random(seeds.nextLong()));
							List<SpinPlan.Step> steps = plan.getSteps();
							SpinPlan.Step last = steps.get(steps.size() - 1);
							String ctx = fakeOuts + "/" + pattern + " n=" + positions + " t=" + target;
							assertEquals(ctx, target, last.getPosition());
							assertEquals(ctx, SpinPlan.Kind.FINAL, last.getKind());
						}
					}
				}
			}
		}
	}

	@Test
	public void landsAtConfiguredDuration()
	{
		Random seeds = new Random(99);
		for (long duration : new long[]{3000, 8000, 30000})
		{
			for (SpinSpeed speed : SpinSpeed.values())
			{
				for (FakeOuts fakeOuts : FakeOuts.values())
				{
					for (int run = 0; run < 200; run++)
					{
						SpinPlan plan = SpinPlan.generate(5, run % 5, duration, speed, fakeOuts, SpinPattern.SWEEP, 0.2, new Random(seeds.nextLong()));
						assertEquals(duration + " " + speed + " " + fakeOuts, duration, plan.getLandMs());
					}
				}
			}
		}
	}

	@Test
	public void stepsAreContiguousAndMoveEveryStep()
	{
		Random seeds = new Random(7);
		for (SpinPattern pattern : SpinPattern.values())
		{
			for (int run = 0; run < 500; run++)
			{
				int n = 2 + run % 4;
				SpinPlan plan = SpinPlan.generate(n, run % n, DURATION_MS, SpinSpeed.NORMAL, FakeOuts.CHAOTIC, pattern, 0.2, new Random(seeds.nextLong()));
				List<SpinPlan.Step> steps = plan.getSteps();
				assertEquals(0, steps.get(0).getStartMs());
				for (int i = 1; i < steps.size(); i++)
				{
					SpinPlan.Step prev = steps.get(i - 1);
					SpinPlan.Step cur = steps.get(i);
					assertEquals(prev.endMs(), cur.getStartMs());
					assertTrue(cur.getHoldMs() > 0);
					assertTrue("highlight must move each step", prev.getPosition() != cur.getPosition());
					if (pattern == SpinPattern.SWEEP && n > 2)
					{
						// sweep only ever steps to a neighbouring chest
						assertEquals(1, Math.abs(prev.getPosition() - cur.getPosition()));
					}
				}
			}
		}
	}

	@Test
	public void mainRunSlowsDown()
	{
		Random seeds = new Random(42);
		for (int run = 0; run < 500; run++)
		{
			SpinPlan plan = SpinPlan.generate(5, 2, DURATION_MS, SpinSpeed.NORMAL, FakeOuts.OFF, SpinPattern.LOOP, 0.2, new Random(seeds.nextLong()));
			List<SpinPlan.Step> steps = plan.getSteps();
			// everything before FINAL is the ease-out; allow 1ms rounding from the rescale
			for (int i = 1; i < steps.size() - 1; i++)
			{
				assertTrue("hold shrank at step " + i, steps.get(i).getHoldMs() + 1 >= steps.get(i - 1).getHoldMs());
			}
			assertTrue(steps.get(0).getHoldMs() < steps.get(steps.size() - 2).getHoldMs());
		}
	}

	@Test
	public void offHasNoFakeOutsAndChaoticAlwaysHasSome()
	{
		Random seeds = new Random(5);
		for (int run = 0; run < 300; run++)
		{
			SpinPlan off = SpinPlan.generate(4, 1, DURATION_MS, SpinSpeed.NORMAL, FakeOuts.OFF, SpinPattern.SWEEP, 0.2, new Random(seeds.nextLong()));
			SpinPlan chaotic = SpinPlan.generate(4, 1, DURATION_MS, SpinSpeed.NORMAL, FakeOuts.CHAOTIC, SpinPattern.SWEEP, 0.2, new Random(seeds.nextLong()));
			assertEquals(0, countFakeOuts(off));
			assertTrue(countFakeOuts(chaotic) >= 2);
		}
	}

	@Test
	public void startingChestVaries()
	{
		// The start must not give away the target.
		Random seeds = new Random(11);
		boolean[] seen = new boolean[5];
		for (int run = 0; run < 400; run++)
		{
			SpinPlan plan = SpinPlan.generate(5, 3, DURATION_MS, SpinSpeed.NORMAL, FakeOuts.LIGHT, SpinPattern.SWEEP, 0.2, new Random(seeds.nextLong()));
			seen[plan.getSteps().get(0).getPosition()] = true;
		}
		for (int i = 0; i < 5; i++)
		{
			assertTrue("never started on " + i, seen[i]);
		}
	}

	@Test
	public void stepAtFindsTheRightStep()
	{
		SpinPlan plan = SpinPlan.generate(3, 0, DURATION_MS, SpinSpeed.NORMAL, FakeOuts.LIGHT, SpinPattern.LOOP, 0.2, new Random(3));
		for (SpinPlan.Step s : plan.getSteps())
		{
			assertEquals(s, plan.stepAt(s.getStartMs()));
			assertEquals(s, plan.stepAt(s.endMs() - 1));
		}
		assertEquals(plan.getSteps().get(plan.getSteps().size() - 1), plan.stepAt(plan.getLandMs() + 100_000));
	}

	@Test
	public void purpleTeasesNeverOnAStop()
	{
		Random seeds = new Random(21);
		int teases = 0;
		for (int run = 0; run < 1000; run++)
		{
			SpinPlan plan = SpinPlan.generate(4, run % 4, DURATION_MS, SpinSpeed.NORMAL, FakeOuts.CHAOTIC, SpinPattern.SWEEP, 0.2, new Random(seeds.nextLong()));
			for (SpinPlan.Step s : plan.getSteps())
			{
				if (s.isPurpleTease())
				{
					teases++;
					assertTrue("tease on a stop", !s.looksLanded());
				}
			}
			SpinPlan none = SpinPlan.generate(4, run % 4, DURATION_MS, SpinSpeed.NORMAL, FakeOuts.CHAOTIC, SpinPattern.SWEEP, 0, new Random(seeds.nextLong()));
			for (SpinPlan.Step s : none.getSteps())
			{
				assertTrue("tease while turned off", !s.isPurpleTease());
			}
		}
		assertTrue("teases should happen", teases > 0);
	}

	@Test
	public void slowerSpeedMeansFewerMoves()
	{
		Random seeds = new Random(8);
		long slowSteps = 0;
		long fastSteps = 0;
		for (int run = 0; run < 300; run++)
		{
			long seed = seeds.nextLong();
			slowSteps += SpinPlan.generate(5, 2, DURATION_MS, SpinSpeed.SLOW, FakeOuts.OFF, SpinPattern.SWEEP, 0, new Random(seed)).getSteps().size();
			fastSteps += SpinPlan.generate(5, 2, DURATION_MS, SpinSpeed.FAST, FakeOuts.OFF, SpinPattern.SWEEP, 0, new Random(seed)).getSteps().size();
		}
		assertTrue("slow " + slowSteps + " vs fast " + fastSteps, slowSteps < fastSteps);
	}

	private static int countFakeOuts(SpinPlan plan)
	{
		int n = 0;
		for (SpinPlan.Step s : plan.getSteps())
		{
			if (s.getKind() == SpinPlan.Kind.NEAR_MISS || s.getKind() == SpinPlan.Kind.FALSE_STOP)
			{
				n++;
			}
		}
		return n;
	}
}

